answer_code:
using System;
using System.Collections.Generic;

public class Solution
{
    public static IComparer<int> ByAbsoluteValue()
    {
        return Comparer<int>.Create((a, b) => Math.Abs(a).CompareTo(Math.Abs(b)));
    }

    public static void SortByAbsoluteValue(List<int> values)
    {
        values.Sort(ByAbsoluteValue());
    }
}

