    private int[] _values;

    public Ring(int[] values)
    {
        _values = values;
    }

    public int Length
    {
        get { return _values.Length; }
    }

    public int this[int index]
    {
        get { return _values[Wrap(index)]; }
        set { _values[Wrap(index)] = value; }
