using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static string SummarizeByInitial(List<string> words)
    {
        var parts = words
            .GroupBy(w => w[0])
            .Select(g => new { Head = g.Key, Count = g.Count() })
            .OrderBy(x => x.Head)
            .Select(x => x.Head + ":" + x.Count);
        return string.Join(", ", parts);
    }

    public static bool AnonymousValuesAreEqual()
    {
        var a = new { Head = 'a', Count = 2 };
        var b = new { Head = 'a', Count = 2 };
        return a.Equals(b);
    }
}

