using System;

class Solution
{
    public static string Quadrant(int x, int y) => (x, y) switch
    {
        (0, 0) => "origin",
        (> 0, > 0) => "I",
        (< 0, > 0) => "II",
        (< 0, < 0) => "III",
        (> 0, < 0) => "IV",
        _ => "axis",
    };
}

