answer_code:
using System;

[Flags]
public enum Permission
{
    None = 0,
    Read = 1,
    Write = 2,
    Execute = 4,
}

class Solution
{
    public static Permission Grant(bool read, bool write, bool exec)
    {
        Permission p = Permission.None;
        if (read) p |= Permission.Read;
        if (write) p |= Permission.Write;
        if (exec) p |= Permission.Execute;
        return p;
    }

    public static bool Has(Permission p, Permission flag) => p.HasFlag(flag);
}

