using System;
using System.Collections.Generic;

class Solution
{
    public static int LookupOrDefault(Dictionary<string, int> dict, string key, int fallback)
    {
        if (dict.TryGetValue(key, out var value))
        {
            return value;
        }
        return fallback;
    }

    public static int SumExisting(Dictionary<string, int> dict, string[] keys)
    {
        int total = 0;
        foreach (var key in keys)
        {
            if (dict.TryGetValue(key, out var value))
            {
                total += value;
            }
        }
        return total;
    }
}

