using System;
using System.Linq;

class Solution
{
    public static double Average(int[] values)
    {
        if (values.Length == 0)
        {
            throw new ArgumentException("空の配列の平均は求められません", nameof(values));
        }
        return values.Average();
    }

    public static int Element(int[] values, int index)
    {
        if (index < 0 || index >= values.Length)
        {
            throw new ArgumentOutOfRangeException(nameof(index), "0 以上 " + values.Length + " 未満で指定してください");
        }
        return values[index];
    }
}

