using System;
using System.Linq;
using System.Collections.Generic;

class Solution
{
    public static List<string> LeftJoin(
        IEnumerable<(int Id, string Name)> people,
        IEnumerable<(int PersonId, string City)> cities)
    {
        return people
            .GroupJoin(cities, p => p.Id, c => c.PersonId, (p, cs) => new { Person = p, Cities = cs })
            .SelectMany(x => x.Cities.DefaultIfEmpty(), (x, c) => x.Person.Name + ":" + (c.City ?? "-"))
            .ToList();
    }
}

