using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    public class LengthComparer : IEqualityComparer<string>
    {
        public bool Equals(string a, string b)
        {
            return a.Length == b.Length;
        }

        public int GetHashCode(string s)
        {
            return s.Length.GetHashCode();
        }
    }

    public static List<string> DistinctByLength(IEnumerable<string> src)
    {
        return src.Distinct(new LengthComparer()).ToList();
    }
}

