using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    public static List<int> InsertAfterFirst(IEnumerable<int> src, int target, int value)
    {
        var list = new LinkedList<int>(src);
        LinkedListNode<int> node = list.Find(target);
        if (node != null)
        {
            list.AddAfter(node, value);
        }
        else
        {
            list.AddLast(value);
        }
        return list.ToList();
    }
}

