using System;
using System.Collections.Generic;

class Solution
{
    public static List<string> Drain(string[] names, int[] priorities)
    {
        var pq = new PriorityQueue<string, int>();
        for (int i = 0; i < names.Length; i++)
        {
            pq.Enqueue(names[i], priorities[i]);
        }
        var result = new List<string>();
        while (pq.Count > 0)
        {
            result.Add(pq.Dequeue());
        }
        return result;
    }
}

