using System;

class Solution
{
    public static int[] MakeFilled(int n, int value)
    {
        var a = new int[n];
        Array.Fill(a, value);
        return a;
    }

    public static int[] Grown(int[] src, int newSize)
    {
        var copy = new int[src.Length];
        Array.Copy(src, copy, src.Length);
        Array.Resize(ref copy, newSize);
        return copy;
    }
}

