using System;
using System.Collections.Generic;

class Solution
{
    public static T MaxOf<T>(IEnumerable<T> src, T fallback) where T : IComparable<T>
    {
        bool found = false;
        T best = fallback;
        foreach (var x in src)
        {
            if (!found || x.CompareTo(best) > 0)
            {
                best = x;
                found = true;
            }
        }
        return found ? best : fallback;
    }
}

