using System;
using System.Collections.Generic;

class Solution
{
    public class Counter
    {
        public int Value = 0;
    }

    public static List<T> CreateMany<T>(int n) where T : new()
    {
        var list = new List<T>();
        for (int i = 0; i < n; i++)
        {
            list.Add(new T());
        }
        return list;
    }

    public static T UnwrapOr<T>(T? v, T fallback) where T : struct
    {
        return v.HasValue ? v.Value : fallback;
    }

    public static bool IsNull<T>(T obj) where T : class
    {
        return obj == null;
    }
}

