using System;
using System.Text.RegularExpressions;

class Solution
{
    public static string Reformat(string date)
    {
        Match m = Regex.Match(date, @"^(?<year>\d{4})-(?<month>\d{2})-(?<day>\d{2})$");
        if (!m.Success)
        {
            return "";
        }
        return m.Groups["day"].Value + "/" + m.Groups["month"].Value + "/" + m.Groups["year"].Value;
    }
}

