using System;
using System.Globalization;

class Solution
{
    public static Money Make(decimal amount, string currency)
    {
        return new Money(amount, currency);
    }
}

class Money : IFormattable
{
    public decimal Amount { get; }
    public string Currency { get; }

    public Money(decimal amount, string currency)
    {
        Amount = amount;
        Currency = currency;
    }

    public string ToString(string format, IFormatProvider provider)
    {
        if (string.IsNullOrEmpty(format))
        {
            format = "G";
        }
        if (provider == null)
        {
            provider = CultureInfo.CurrentCulture;
        }
        string number = Amount.ToString("0.00", provider);
        switch (format)
        {
            case "G": return Currency + " " + number;
            case "N": return number;
            case "S": return Currency;
            default: throw new FormatException("Unsupported format string: " + format);
        }
    }

    public override string ToString()
    {
        return ToString("G", CultureInfo.InvariantCulture);
    }
}

