        var big = new int[50];
        for (int i = 0; i < big.Length; i++) { big[i] = i; }
        var bigResult = Solution.AllDoubledAsync(big).GetAwaiter().GetResult();
        bool allOk = bigResult.Length == 50;
        for (int i = 0; i < bigResult.Length && allOk; i++) { if (bigResult[i] != i * 2) { allOk = false; } }
        Check(allOk, "many_tasks_in_order");
        if (failed > 0) { System.Console.WriteLine("test result: FAILED"); return 1; }
        System.Console.WriteLine("test result: ok");
        return 0;
    }
}

